import AppKit

/// The space catalog approved in arc-central-selections.json: 31 Central
/// drawings, the other 25 the same Ionicons glyphs Arc offers. Keep the
/// existing symbol keys so saved spaces and older sync clients keep their
/// choices. Folders share these drawings; the app's controls keep their own.
@MainActor
enum SpaceIconArt {
    struct Entry {
        let arc: String
        let source: String
        let words: [String]
        let svg: String
    }

    private static var made: [String: NSImage] = [:]

    static func art(_ symbol: String) -> NSImage? {
        if let hit = made[symbol] { return hit }
        guard let entry = catalog[symbol], let image = NSImage(data: Data(entry.svg.utf8)) else { return nil }
        image.isTemplate = true
        made[symbol] = image
        return image
    }

